Q: Why does my code break for huge integer values? A: <p>If you are learning C++, stop writing C. Don't pass around pointers to integers when you only read integers. Also,</p>
<p>Always, <em>always</em> compile your programs with at least <code>-Wall -Wpedantic -Wextra -Werror</code>. If you did that, the compiler would have pointed out that two of your functions may exit without returning a value.</p>
<hr />
<p>This is a two-part question. You need a source of primes, and a way to check that big number for prime factors.</p>
<p>Here's a class that returns the prime numbers one by one.</p>
<pre class="lang-cpp prettyprint-override"><code>#include &lt;vector&gt;
#include &lt;cstdint&gt;
#include &lt;iostream&gt;
#include &lt;algorithm&gt;

class primes{
public:
    uint64_t next();
private:
    std::vector&lt;uint64_t&gt; prime_numbers{};

    bool is_prime(uint64_t n);
};

bool primes::is_prime(uint64_t n) {
    return std::all_of(
        prime_numbers.begin(), prime_numbers.end(),
        [n](uint64_t p){ return n % p != 0; }
    );
}


uint64_t primes::next() {
    if (prime_numbers.empty()) {
        prime_numbers.push_back(2);
        return 2;
    }

    uint64_t candidate = prime_numbers.back() + 1;
    while (true) {
        if (is_prime(candidate)) {
            prime_numbers.push_back(candidate);
            return candidate;
        }
        ++candidate;
    }
}
</code></pre>
<p>And here's how to call it:</p>
<pre class="lang-cpp prettyprint-override"><code>
int main()
{
    primes p;
    const uint64_t six = 600851475143ul;
    for (int i = 0; i &lt; 1000; ++i) {
        uint64_t prime = p.next();
        if (six % prime == 0) {
            std::cout &lt;&lt; prime &lt;&lt; &quot;\n&quot;;
            // break; here to print just the smallest prime factor
        }
    }
}

</code></pre>
